    A.ObservePut(m[k := x], j, y);
    A.ObserveDrop(m[k := x][j := y], k);
    A.ObserveDrop(m, k);
    A.ObservePut(K.Drop(m, k), j, y);
    if k == j {
      var lhs := (map q | q in m[k := x][j := y] && q != k :: m[k := x][j := y][q]);
      var rhs := (map q | q in m && q != k :: m[q]);
      assert lhs.Keys == rhs.Keys;
      forall q | q in lhs
        ensures q in rhs && lhs[q] == rhs[q]
      {
        assert q in rhs;
        assert lhs[q] == rhs[q];
      }
      A.Equal(lhs, rhs);
    } else {
